// Складаємо steps/state за contracts/setup-result.schema.json. Ітерація 1 нічого не створює,
// тому outcome тут може бути лише ok | missing | skipped.
//
// Канон виміряний 2026-08-07 по всіх 16 Active-воркспейсах, не взятий зі старого полотна.
const CANON_WEBHOOKS = [
  { events: ['lead_replied'], url: 'https://n8n.coldunicorn.com/webhook/replies-classification' },
  { events: ['tag_attached', 'tag_removed'], url: 'https://n8n.coldunicorn.com/webhook/bison-replies-hub' },
];
// preMQL і OOO — 16/16. MQL сюди НЕ входить: він є лише в 7 із 16, і це не діра — у Bison MQL
// народжується з вбудованого тега Interested (16/16), а bison-lead-enrichment читає
// includes('interested') || includes('mql'). Створити MQL означало б дати клієнту другий,
// гірше підключений маршрут до тієї ж кваліфікації.
const CANON_TAGS = ['preMQL', 'OOO'];
// Кампанії лише звіряємо. Створювати їх не можна: копія трьох sequence-steps на старому полотні
// побайтово однакова й жіночим польським із зашитим {PANIEKAMILU}, а сліпий create уже дав
// Bent Iron PL шість кампаній замість трьох.
const CANON_CAMPAIGNS = ['OOO automation | general', 'OOO automation | male', 'OOO automation | female'];

const input = $('Start').first().json;
const client = $('Resolve Client').first().json ?? {};
const resolution = $('Resolve Workspace').first().json ?? {};

// Кожен із трьох списків може прийти кількома айтемами (пагінація /api/campaigns іде
// через links.next), тому збираємо .all() і склеюємо data.
const collect = (nodeName) => {
  let items;
  try { items = $(nodeName).all(); } catch (e) { return { rows: [], error: String(e.message ?? e) }; }
  const rows = [];
  let error = null;
  for (const item of items) {
    const j = item.json ?? {};
    if (j.error) { error = String(j.error?.message ?? j.error); continue; }
    if (Array.isArray(j.data)) rows.push(...j.data);
    else if (Array.isArray(j)) rows.push(...j);
  }
  return { rows, error };
};

const step = (outcome, present = [], missing = [], error = null) => ({
  outcome, present, ...(missing.length ? { missing } : {}), ...(error ? { error } : {}),
});

// Ідентичність вебхука — events + url, НІКОЛИ не назва. Вебхук UniTalk зветься
// "Reply Classification" проти "Reply classification" у решти пʼятнадцяти, і звірка за назвою
// створила б сімнадцятий вебхук на lead_replied: дві доставки на відповідь, два ліди.
const hookKey = (events, url) => `${[...(events ?? [])].map(String).sort().join('+')} ${String(url ?? '').trim()}`;

const storedKey = Boolean(client.api_key);

// У Bison немає GET на токени воркспейсу — на відміну від Aimfox, де вендора можна перепитати.
// Тому єдине джерело правди про ключ тут — рядок конектора.
const key = storedKey
  ? step('ok', ['client_sequencers.api_key'])
  : step('missing', [], ['api_key'], 'Bison has no token-list endpoint: a lost key cannot be re-read, only re-minted');

const webhooks = (() => {
  if (!storedKey) return step('skipped', [], [], 'no workspace key stored yet');
  const { rows, error } = collect('List Webhooks');
  if (error) return step('skipped', [], [], `vendor call failed: ${error}`);
  const present = rows.map((w) => hookKey(w.events, w.url));
  const missing = CANON_WEBHOOKS.map((c) => hookKey(c.events, c.url)).filter((k) => !present.includes(k));
  return step(missing.length ? 'missing' : 'ok', present, missing);
})();

const tags = (() => {
  if (!storedKey) return step('skipped', [], [], 'no workspace key stored yet');
  const { rows, error } = collect('List Tags');
  if (error) return step('skipped', [], [], `vendor call failed: ${error}`);
  const present = rows.map((t) => String(t?.name ?? '').trim()).filter(Boolean);
  const missing = CANON_TAGS.filter((n) => !present.includes(n));
  return step(missing.length ? 'missing' : 'ok', present, missing);
})();

const campaigns = (() => {
  if (!storedKey) return step('skipped', [], [], 'no workspace key stored yet');
  const { rows, error } = collect('List Campaigns');
  if (error) return step('skipped', [], [], `vendor call failed: ${error}`);
  const names = rows.map((c) => String(c?.name ?? '').trim());
  // Дублікати показуємо явно: Bent Iron PL має шість кампаній замість трьох, і "×2" у present —
  // єдине місце, де це видно, не відкриваючи вендора.
  const present = CANON_CAMPAIGNS
    .map((n) => ({ n, count: names.filter((x) => x === n).length }))
    .filter((x) => x.count > 0)
    .map((x) => (x.count > 1 ? `${x.n} ×${x.count}` : x.n));
  const missing = CANON_CAMPAIGNS.filter((n) => !names.includes(n));
  const dup = present.some((p) => p.includes(' ×'));
  return step(
    missing.length ? 'missing' : 'ok',
    present,
    missing,
    dup ? 'duplicate OOO campaigns at the vendor — reported, never resolved by creating more' : null,
  );
})();

const steps = { key, webhooks, tags, campaigns };

const decided = [key, webhooks, tags, campaigns];
const state = decided.every((s) => s.outcome === 'ok') ? 'configured'
  : decided.every((s) => s.outcome !== 'ok') ? 'missing'
  : 'partial';

return [{ json: {
  client_id: input.client_id,
  client_name: client.client_name ?? null,
  sequencer: 'emailbison',
  dry_run: true,
  read_only_iteration: true,
  resolved: resolution.resolved ?? null,
  state,
  steps,
} }];

const input = $('Start').first().json;
const client = $('Resolve Client').first().json ?? {};
const resolution = $('Resolve Workspace').first().json ?? {};

// Неіснуючий клієнт — помилка того, хто викликав, а не стан провіженінгу. Але сказати про це
// треба вголос: мовчазний обрив із status=success — це те, як зникли ліди Audytel.
const state = resolution.client_missing ? 'client_not_found' : 'needs_selection';
const reason = resolution.client_missing ? 'no such client, or it has no enabled emailbison connector'
  : resolution.ambiguous ? 'more than one workspace matches the client name'
  : resolution.list_error ? `could not list workspaces: ${resolution.list_error}`
  : 'no workspace matches the client name';

return [{ json: {
  client_id: input.client_id,
  client_name: client.client_name ?? null,
  sequencer: 'emailbison',
  dry_run: true,
  read_only_iteration: true,
  resolved: null,
  state,
  reason,
  candidates: resolution.candidates ?? [],
  steps: {
    key: { outcome: 'skipped' }, webhooks: { outcome: 'skipped' },
    tags: { outcome: 'skipped' }, campaigns: { outcome: 'skipped' },
  },
} }];

// Порядок резолву: явний id → уже записаний за клієнтом → ТОЧНИЙ збіг назви → кандидати.
// Той самий порядок, що в aimfox-workspace-setup, і з тієї ж причини: для вже заведеного
// клієнта воркспейс відомий з бази, і шукати за назвою не треба взагалі.
//
// Неоднозначність ніколи не вирішується здогадкою — інваріант 2. У Bison це важить більше,
// ніж в Aimfox: однойменних воркспейсів тут помітно більше, тому в кандидатах віддаємо ще
// personal_team / main / parent_id — саме вони дають людині шанс відрізнити два однакові рядки.
const input = $('Start').first().json;
const client = $('Resolve Client').first().json ?? {};
const listRaw = $('List Workspaces').first().json ?? {};
const claimedRaw = $('Read Claimed').first().json ?? {};

const list = Array.isArray(listRaw.data) ? listRaw.data
  : Array.isArray(listRaw.workspaces) ? listRaw.workspaces
  : [];
// Id у Bison — ціле число. Скрізь тримаємо його рядком, бо в client_sequencers він text,
// і порівняння 73 === '73' мовчки дало б "не закріплений".
const idOf = (w) => String(w?.id ?? w?.workspace_id ?? '').trim();
const nameOf = (w) => String(w?.name ?? '').trim();

const claimed = new Set((claimedRaw.claimed ?? []).map(String));
const listError = listRaw.error ? String(listRaw.error?.message ?? listRaw.error) : null;
const base = { candidates: [], list_error: listError, workspaces_seen: list.length };

// Resolve Client має alwaysOutputData, тож неіснуючий клієнт приходить як {} замість того, щоб
// тихо обірвати ланцюжок. Кажемо про це вголос — мовчазний успіх гірший за помилку.
if (!String(client.client_name ?? '').trim()) {
  return [{ json: { ...base, resolved: null, client_missing: true } }];
}

const find = (id) => list.find((w) => idOf(w) === id) ?? null;
const decorate = (id, matched_by) => {
  const w = find(id);
  return {
    workspace_id: id,
    name: w ? nameOf(w) || null : null,
    matched_by,
    personal_team: w?.personal_team ?? null,
    parent_id: w?.parent_id ?? null,
  };
};

const explicit = String(input.workspace_id ?? '').trim();
if (explicit) return [{ json: { ...base, resolved: decorate(explicit, 'explicit') } }];

const stored = String(client.stored_workspace_id ?? '').trim();
if (stored) return [{ json: { ...base, resolved: decorate(stored, 'stored') } }];

const target = String(client.client_name).trim().toLowerCase();
const matches = list.filter((w) => nameOf(w).toLowerCase() === target);
if (matches.length === 1) return [{ json: { ...base, resolved: decorate(idOf(matches[0]), 'name') } }];

// Кандидати — усе, що ще не закріплене за жодним клієнтом. Показати зайнятий воркспейс означає
// запросити те саме хибне призначення, через яке воркспейс GIC опинився на Prac.Finansowa.
const candidates = list
  .filter((w) => idOf(w) && !claimed.has(idOf(w)))
  .map((w) => ({
    workspace_id: idOf(w),
    name: nameOf(w) || null,
    personal_team: w?.personal_team ?? null,
    main: w?.main ?? null,
    parent_id: w?.parent_id ?? null,
  }));

return [{ json: { ...base, resolved: null, candidates, ambiguous: matches.length > 1 } }];
